(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.02+t*0.35)*6;
  const w2y = Math.cos(sy*0.022+t*0.45)*8 + Math.sin(sx*0.018-t*0.38)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.07, 2.2],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.5],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.4],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.08, 2.0],
    [60+Math.sin(t*0.55+3)*70, 50+Math.cos(t*0.65+4)*50, 0.1, 1.6],
    [420+Math.cos(t*0.42+1)*80, 200+Math.sin(t*0.48+2)*60, 0.075, 2.3]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.5);
    aS2 += Math.cos(d*f*1.3-t*sp*0.8+0.7);
    iS2 += Math.cos(d*f*0.5+t*sp*0.4+2.8);
  }
  const act=aS/8, inh=iS/8, act2=aS2/8, inh2=iS2/8;
  const bg = (Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*0.95))/2
    + Math.sin((fx+fy)*0.1+t*2.2)*0.2 + Math.sin((fx-fy)*0.085-t*1.8)*0.2
    + Math.sin(fx*0.06+fy*0.04-t*1.5)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0)
    +Math.sin(dist*0.08-ang*2-t*2.2)*0.5)*0.35;
  const cross = Math.sin(fx*0.12+t*0.8)*Math.sin(fy*0.12-t*0.6)*0.3;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.25 + spiral)*2.0);
  const rd2 = Math.tanh((act2*0.7 - inh2*0.5 + cross + spiral*0.5)*1.8);
  const feedback = Math.tanh((rd1*0.6+rd2*0.4)*Math.sin(t*0.2)*0.3 + rd1*rd2*1.5);
  const cell = Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.4)*1.4)*0.25;
  const fine = Math.sin(fx*0.3+t*1.5)*Math.sin(fy*0.28-t*1.2)*Math.abs(rd1)*0.15;
  const blend = feedback*0.55 + rd1*0.2 + cell*0.15 + fine, v = blend*0.5+0.5;
  const pal = [[5,12,52],[12,55,95],[18,110,125],[25,165,145],[180,190,80],[215,145,65],[195,80,75],[140,40,65],[75,18,48],[30,8,38],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(feedback*Math.PI)*0.15;
  const edge=Math.abs(feedback)>0.65?1.12:Math.abs(rd1)>0.75?1.08:1.0;
  const glow=Math.max(0,feedback)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
